      "hl.btn.copyMarked": "نسخ كنص عادي",
      "hl.btn.clearAll": "مسح الكل",
      "hl.placeholder": "الصق أو اكتب نصك هنا، ثم حدّد جزءًا منه واضغط زر تنسيق بالأعلى...",
      "hl.status.selectFirst": "حدّد جزءًا من النص أولًا، ثم اضغط زر تنسيق.",
      "hl.status.empty": "اكتب أو الصق نص أولًا.",
